-- Drizzle generated this CREATE TABLE because newsletter_subscribers was added to the schema without a prior migration.
-- Wrapped in IF NOT EXISTS to stay idempotent: no-op if the table was already pushed via drizzle-kit push, creates it otherwise.
CREATE TABLE IF NOT EXISTS "newsletter_subscribers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"email" text NOT NULL,
	"locale" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "newsletter_subscribers_email_unique" UNIQUE("email")
);
